        "items": [
          {
            "type": 1,
            "content": {
              "json": "> **Guardrail:** reads Azure Resource Graph state for **SQL Server enabled by Azure Arc**. Readiness and inventory only, not billing, entitlement, compliance or approval. PAYG, Paid and LicenseOnly are core-based; Server+CAL must be handled separately (LicenseOnly). Form factor and core counts come from guest metadata and are preliminary.\n"
            },
            "name": "disclaimer",
            "conditionalVisibility": {
              "parameterName": "Language",
              "comparison": "isEqualTo",
              "value": "EN"
            }
          },
          {
            "type": 1,
            "content": {
              "json": "> **Limites:** lê o estado do Azure Resource Graph para **SQL Server habilitado pelo Azure Arc**. Apenas prontidão e inventário, não é cobrança, direito de uso, conformidade nem aprovação. PAYG, Paid e LicenseOnly são por núcleo; Server+CAL deve ser tratado à parte (LicenseOnly). Tipo de máquina e núcleos vêm de metadados do convidado e são preliminares.\n"
            },
            "name": "disclaimer-pt",
            "conditionalVisibility": {
              "parameterName": "Language",
              "comparison": "isEqualTo",
              "value": "PT"
            }
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.azurearcdata/sqlserverinstances'\n| extend HostId = tolower(tostring(properties.containerResourceId))\n| where HostId contains '/providers/microsoft.hybridcompute/machines/'\n| extend Edition=tostring(properties.edition), Version=tostring(properties.version), InstanceLicenseType=tostring(properties.licenseType)\n| extend EditionRank = case(Edition has 'Enterprise', 6, Edition has 'Standard', 5, Edition has 'Web', 4, Edition has 'Express', 3, Edition has 'Developer', 2, Edition has 'Evaluation', 1, 0)\n| extend SqlVersionMajor = case(Version has 'SQL Server 2014' or Version startswith '12.', 'SQL Server 2014', Version has 'SQL Server 2016' or Version startswith '13.', 'SQL Server 2016', Version has 'SQL Server 2017' or Version startswith '14.', 'SQL Server 2017', Version has 'SQL Server 2019' or Version startswith '15.', 'SQL Server 2019', Version has 'SQL Server 2022' or Version startswith '16.', 'SQL Server 2022', Version has 'SQL Server 2025' or Version startswith '17.', 'SQL Server 2025', isnotempty(Version), Version, 'Not identified')\n| summarize Instances=count(), ActiveInstances=countif(InstanceLicenseType !~ 'HADR'), HadrInstances=countif(InstanceLicenseType =~ 'HADR'), FreeOrTestInstances=countif(Edition has 'Developer' or Edition has 'Evaluation' or Edition has 'Express'), ServerCALInstances=countif(InstanceLicenseType =~ 'ServerCAL'), EsuVersionInstances=countif(SqlVersionMajor in ('SQL Server 2014','SQL Server 2016')), TopEditionRank=max(EditionRank), StandardCoreLimit=max(iff(Edition has 'Standard', iff(SqlVersionMajor == 'SQL Server 2025', 32, 24), 0)), Editions=make_set(Edition), Versions=make_set(SqlVersionMajor), InstanceLicenseTypes=make_set(InstanceLicenseType) by HostId\n| extend TopEdition = case(TopEditionRank == 6, 'Enterprise', TopEditionRank == 5, 'Standard', TopEditionRank == 4, 'Web', TopEditionRank == 3, 'Express', TopEditionRank == 2, 'Developer', TopEditionRank == 1, 'Evaluation', 'Not identified')\n| extend HadrOnlySignal = Instances > 0 and ActiveInstances == 0\n| join kind=leftouter (\n    resources\n    | where type =~ 'microsoft.hybridcompute/machines'\n    | extend HostId = tolower(id)\n    | project HostId, MachineName=tostring(name), ArcStatus=tostring(properties.status), SqlDiscovered=tostring(properties.detectedProperties.mssqldiscovered), LogicalCoreCount=toint(properties.detectedProperties.logicalCoreCount), PhysicalCoreCount=toint(properties.detectedProperties.coreCount), SocketCount=toint(properties.detectedProperties.processorCount), Manufacturer=tostring(properties.detectedProperties.manufacturer), HardwareModel=tostring(properties.detectedProperties.model), OsType=tostring(properties.osType), OsName=tostring(properties.osName), LastStatusChange=todatetime(properties.lastStatusChange), MachineRG=resourceGroup, MachineSub=subscriptionId\n) on HostId\n| join kind=leftouter (\n    resources\n    | where type =~ 'microsoft.hybridcompute/machines/extensions'\n    | where tostring(properties.publisher) =~ 'Microsoft.AzureData'\n    | where tostring(properties.type) in~ ('WindowsAgent.SqlServer','LinuxAgent.SqlServer')\n    | extend HostId = tolower(substring(id, 0, indexof(tolower(id), '/extensions')))\n    | extend HostLicenseTypeRaw = tostring(properties.settings.LicenseType)\n    | extend HostLicenseType = case(HostLicenseTypeRaw =~ 'PAYG', 'PAYG', HostLicenseTypeRaw =~ 'Paid', 'Paid', HostLicenseTypeRaw =~ 'LicenseOnly', 'LicenseOnly', isempty(HostLicenseTypeRaw), 'Not reported', HostLicenseTypeRaw)\n    | extend UsePhysicalCoreLicenseRaw = tostring(properties.settings.UsePhysicalCoreLicense.IsApplied)\n    | extend UsePhysicalCoreLicense = case(UsePhysicalCoreLicenseRaw =~ 'true', 'Applied', UsePhysicalCoreLicenseRaw =~ 'false', 'Not applied', 'Not reported')\n    | project HostId, ExtensionState=tostring(properties.provisioningState), ExtensionVersion=tostring(properties.typeHandlerVersion), HostLicenseType, EnableESU=tostring(properties.settings.enableExtendedSecurityUpdates), UsePhysicalCoreLicense, RecurringPAYGConsent=tostring(properties.settings.ConsentToRecurringPAYG.Consented), RecurringPAYGConsentTimestamp=tostring(properties.settings.ConsentToRecurringPAYG.ConsentTimestamp)\n) on HostId\n| join kind=leftouter (\n    resources\n    | where type =~ 'microsoft.hybridcompute/machines/extensions'\n    | where tostring(properties.publisher) =~ 'Microsoft.AzureData'\n    | where tostring(properties.provisioningState) == 'Succeeded'\n    | where tostring(properties.settings.LicenseType) != 'PAYG'\n    | extend HostId=tolower(substring(id,0,indexof(id,'/extensions')))\n    | summarize ScriptExtensionMatches=count(), ScriptMatchedExtensionTypes=make_set(tostring(properties.type)) by HostId\n) on HostId\n| extend HostLicenseType=coalesce(HostLicenseType,'Not reported'), UsePhysicalCoreLicense=coalesce(UsePhysicalCoreLicense,'Not reported'), ScriptExtensionMatches=coalesce(ScriptExtensionMatches,0)\n| extend ResourceGroup=coalesce(MachineRG, tostring(split(HostId,'/')[4])), SubscriptionId=coalesce(MachineSub, tostring(split(HostId,'/')[2]))\n| extend IsLinux = OsType =~ 'linux'\n| extend HwText = tolower(strcat(HardwareModel, ' ', Manufacturer))\n| extend IsVm = HwText contains 'virtual' or HwText contains 'vmware' or HwText contains 'kvm' or HwText contains 'hvm' or HwText contains 'standard pc' or HwText contains 'google' or HwText contains 'nutanix' or HwText contains 'openstack' or HwText contains 'amazon' or HwText contains 'bhyve' or HwText contains 'xen' or HwText contains 'qemu' or HwText contains 'innotek' or HwText contains 'red hat'\n| extend ForeignCloud = HwText contains 'amazon' or HwText contains 'google'\n| extend FormFactor = case(IsVm, 'VM', isnotempty(HardwareModel) and isnotempty(Manufacturer), 'PHYSICAL', 'UNKNOWN')\n| extend RawCores = iff(FormFactor == 'PHYSICAL', coalesce(PhysicalCoreCount, LogicalCoreCount), coalesce(LogicalCoreCount, PhysicalCoreCount))\n| extend CoreEstimate = case(\n    TopEdition in ('Express','Developer','Evaluation') or (HadrOnlySignal and not(IsLinux)), tolong(0),\n    TopEdition == 'Not identified' or isnull(RawCores) or RawCores <= 0, long(null),\n    TopEdition == 'Standard', tolong(max_of(4, min_of(RawCores, StandardCoreLimit))),\n    tolong(max_of(4, RawCores)))\n| extend ReviewCode = case(\n    HostLicenseType == 'Paid' and TopEdition in ('Enterprise','Standard') and ActiveInstances > 0, 'PAID_REVIEW',\n    HostLicenseType == 'Paid' and HadrOnlySignal, 'PAID_HADR',\n    HostLicenseType == 'PAYG', 'ALREADY_PAYG',\n    HostLicenseType == 'LicenseOnly', 'LICENSEONLY',\n    HostLicenseType == 'Not reported', 'NOT_REPORTED',\n    FreeOrTestInstances > 0, 'FREE_TEST',\n    'REVIEW')\n| extend ScriptCode = case(isempty(MachineName), 'NO_MACHINE', SqlDiscovered !~ 'true', 'NO_DISCOVERY', ScriptExtensionMatches > 0, 'MATCH', 'NO_EXT')\n| extend RiskIfConverted = ScriptCode == 'MATCH' and (HostLicenseType =~ 'LicenseOnly' or ServerCALInstances > 0 or UsePhysicalCoreLicense == 'Applied')\n| extend PriorityNum = case(\n    isempty(MachineName) or ArcStatus !~ 'Connected' or isempty(ExtensionState) or ExtensionState !~ 'Succeeded' or RiskIfConverted, 1,\n    HadrInstances > 0 or FreeOrTestInstances > 0 or HostLicenseType == 'Not reported' or SqlDiscovered !~ 'true' or (EsuVersionInstances > 0 and EnableESU !~ 'true') or ForeignCloud or ServerCALInstances > 0, 2,\n    3)\n| summarize Hosts=count(), Payg=countif(HostLicenseType == 'PAYG'), Paid=countif(HostLicenseType == 'Paid'), LicOnly=countif(HostLicenseType == 'LicenseOnly'), NotRep=countif(HostLicenseType == 'Not reported'), Match=countif(ScriptCode == 'MATCH'), High=countif(PriorityNum == 1), Disc=countif(isnotempty(MachineName) and ArcStatus !~ 'Connected'), NoMach=countif(isempty(MachineName)), Pcore=countif(UsePhysicalCoreLicense == 'Applied'), HadrOnly=countif(HadrOnlySignal), Cal=countif(ServerCALInstances > 0), Esu=countif(EsuVersionInstances > 0 and EnableESU !~ 'true'), CoresReview=sumif(CoreEstimate, ReviewCode == 'PAID_REVIEW'), CoresAll=sum(CoreEstimate)\n| extend Items = pack_array(\n    pack('Metric', iff('{Language}'=='PT', 'Hosts com instância SQL', 'Hosts with SQL instances'), 'Value', Hosts),\n    pack('Metric', iff('{Language}'=='PT', 'Hosts com máquina Arc no ARG', 'Hosts with Arc machine in ARG'), 'Value', Hosts - NoMach),\n    pack('Metric', iff('{Language}'=='PT', 'Já em PAYG', 'Already PAYG'), 'Value', Payg),\n    pack('Metric', iff('{Language}'=='PT', 'Paid (SA/assinatura)', 'Paid (SA/subscription)'), 'Value', Paid),\n    pack('Metric', iff('{Language}'=='PT', 'LicenseOnly', 'LicenseOnly'), 'Value', LicOnly),\n    pack('Metric', iff('{Language}'=='PT', 'LicenseType não definido', 'LicenseType not set'), 'Value', NotRep),\n    pack('Metric', iff('{Language}'=='PT', 'Script selecionaria (ARG)', 'Script would select (ARG)'), 'Value', Match),\n    pack('Metric', iff('{Language}'=='PT', '🔴 Hosts prioridade alta', '🔴 High priority hosts'), 'Value', High),\n    pack('Metric', iff('{Language}'=='PT', 'Arc desconectado', 'Arc not connected'), 'Value', Disc),\n    pack('Metric', iff('{Language}'=='PT', 'Instância sem máquina Arc (residual?)', 'Instance without Arc machine (stale?)'), 'Value', NoMach),\n    pack('Metric', iff('{Language}'=='PT', 'Sinal Server+CAL', 'Server+CAL signal'), 'Value', Cal),\n    pack('Metric', iff('{Language}'=='PT', 'pCore aplicado', 'pCore applied'), 'Value', Pcore),\n    pack('Metric', iff('{Language}'=='PT', 'Hosts somente HA/DR', 'HA/DR only hosts'), 'Value', HadrOnly),\n    pack('Metric', iff('{Language}'=='PT', 'SQL 2014/2016 sem ESU', 'SQL 2014/2016 without ESU'), 'Value', Esu),\n    pack('Metric', iff('{Language}'=='PT', 'Núcleos estimados - Paid a revisar (não é cobrança)', 'Core estimate - Paid review scope (not billing)'), 'Value', CoresReview),\n    pack('Metric', iff('{Language}'=='PT', 'Núcleos estimados - todos (não é cobrança)', 'Core estimate - all hosts (not billing)'), 'Value', CoresAll))\n| project Items\n| mv-expand Items\n| project Metric=tostring(Items.Metric), Value=tolong(Items.Value)\n",
              "size": 0,
              "title": "Snapshot / Panorama PAYG",
              "noDataMessage": "No rows returned for the selected subscriptions. / Nenhuma linha para as assinaturas selecionadas.",
              "showExportToExcel": true,
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscription}"
              ],
              "visualization": "tiles",
