          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.hybridcompute/machines/extensions'\n| where tostring(properties.publisher) =~ 'Microsoft.AzureData'\n| where tostring(properties.type) in~ ('WindowsAgent.SqlServer','LinuxAgent.SqlServer')\n| extend LicenseType = iff(isempty(tostring(properties.settings.LicenseType)), 'Not reported', tostring(properties.settings.LicenseType))\n| summarize Hosts=count() by LicenseType\n| order by Hosts desc\n",
              "size": 0,
              "title": "Hosts by LicenseType / Hosts por LicenseType",
