              "version": "KqlItem/1.0",
              "query": "resources\n| where type =~ 'microsoft.azurearcdata/sqlserverinstances'\n| where tolower(tostring(properties.containerResourceId)) contains '/providers/microsoft.hybridcompute/machines/'\n| extend Version=tostring(properties.version)\n| extend SqlVersionMajor = case(Version has 'SQL Server 2014' or Version startswith '12.', 'SQL Server 2014', Version has 'SQL Server 2016' or Version startswith '13.', 'SQL Server 2016', Version has 'SQL Server 2017' or Version startswith '14.', 'SQL Server 2017', Version has 'SQL Server 2019' or Version startswith '15.', 'SQL Server 2019', Version has 'SQL Server 2022' or Version startswith '16.', 'SQL Server 2022', Version has 'SQL Server 2025' or Version startswith '17.', 'SQL Server 2025', isnotempty(Version), Version, 'Not identified')\n| summarize Instances=count() by SqlVersionMajor\n| order by SqlVersionMajor asc\n",
